rust_api.example_usage:
// 创建分支探索不同方案
ctx.create_branch("refactor-v1", "main")?;
ctx.checkout("refactor-v1")?;
// ... 探索 ...

ctx.checkout("main")?;
ctx.create_branch("refactor-v2", "main")?;
ctx.checkout("refactor-v2")?;
// ... 探索 ...

// 合并最佳方案
ctx.checkout("main")?;
ctx.merge("refactor-v1", "main", MergeStrategy::Selective)?;
